export function translate(language, key) {
  const sourceKey = sourcePhraseKeys[key] || key;
  if (key === 'tagline') return taglines[language] || taglines.sq;
  return messages[language]?.[key] || supplementalMessages[language]?.[key] || phraseCatalogs[language]?.[sourceKey] || messages.sq[key] || supplementalMessages.sq[key] || phraseCatalogs.sq[sourceKey] || key;
}

